    # Add upper bounds for edges (belt capacity or infinite)
    for edge_id, edge in graph.edges.items():
        idx = edge_to_idx[edge_id]
        if use_belt_limits:
            upper_bound = edge.capacity if edge.capacity > 0 else 10000.0
        else:
