    cs.optimize()

    # Get the reduced system
    active_vars, eq_matrix, eq_rhs, ineq_matrix, ineq_rhs, objective = (
        cs.get_reduced_system()
    )

    # If no active variables, return zero flows
    if not active_vars:
        return (True, {eid: 0.0 for eid in edge_ids}, "")

    # Solve using pylinprog (vendored, untyped)
    resolution, reduced_solution = linsolve(  # type: ignore[no-untyped-call]
        objective,
        ineq_left=ineq_matrix,
        ineq_right=ineq_rhs,
        eq_left=eq_matrix,
